query:
CREATE TABLE IF NOT EXISTS community_likes (
  id BIGSERIAL PRIMARY KEY,
  deck_id BIGINT NOT NULL REFERENCES community_decks(id) ON DELETE CASCADE,
  player_id UUID NOT NULL REFERENCES players(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(deck_id, player_id)
);
CREATE INDEX IF NOT EXISTS idx_community_likes_deck ON community_likes(deck_id);
CREATE INDEX IF NOT EXISTS idx_community_likes_player ON community_likes(player_id);

